// naive_Poisson_master.js
// Shared math for the MASTER NODE (SPARQL & SQL)
// =============================================================

function zeros(n, m) {
    var arr = [];
    for (var i = 0; i &lt; n; i++) {
        var row = [];
        for (var j = 0; j &lt; m; j++) row.push(0.0);
        arr.push(row);
    }
    return arr;
}

function fillVector(n, val) {
    var vec = [];
    for (var i = 0; i &lt; n; i++) vec.push(val);
    return vec;
}

function matVec(A, x) {
    var r = [];
    for (var i = 0; i &lt; A.length; i++) r.push(0.0);
    for (var i = 0; i &lt; A.length; i++)
        for (var j = 0; j &lt; x.length; j++)
            r[i] += A[i][j] * x[j];
    return r;
}

function matInv(A) {
    var n = A.length;
    var M = [];
    var I = zeros(n, n);

    for (var i = 0; i &lt; n; i++) {
        M.push(A[i].slice());
        I[i][i] = 1.0;
    }

    for (var i = 0; i &lt; n; i++) {
        var f = M[i][i];
        if (Math.abs(f) &lt; 1e-12) throw new Error("Singular Hesseian");

        for (var j = 0; j &lt; n; j++) {
            M[i][j] /= f;
            I[i][j] /= f;
        }

        for (var k = 0; k &lt; n; k++) {
            if (k === i) continue;
            var g = M[k][i];
            for (var j = 0; j &lt; n; j++) {
                M[k][j] -= g * M[i][j];
                I[k][j] -= g * I[i][j];
            }
        }
    }
    return I;
}

function poisson_master_update(slave_results, beta_old, p, alpha, ridge) {
    var XTWX = zeros(p, p);
    var XTWZ = fillVector(p, 0.0);
    var n_total = 0;

    for (var k = 0; k &lt; slave_results.length; k++) {
        matAdd(XTWX, slave_results[k].xtwx);
        vecAdd(XTWZ, slave_results[k].xtwz);
        n_total += slave_results[k].n;
    }

    for (var i = 0; i &lt; p; i++) {
        XTWX[i][i] += ridge;
    }

    var inv = matInv(XTWX);
    var beta_new = matVec(inv, XTWZ);

    var beta_final = fillVector(p, 0.0);
    for (var i = 0; i &lt; p; i++) {
        beta_final[i] = alpha * beta_new[i] + (1.0 - alpha) * beta_old[i];
    }

    return { 
        beta: beta_final, 
        cov: inv, 
        n: n_total 
    };
}
The poisson_master_update(slave_results, beta_old, p, alpha, ridge) function performs global aggregation and parameter updates:
- Sums xtwx, xtwz, and sample sizes n across all slave inputs.
- Applies the ridge value to the diagonal elements of the aggregated \(X^TWX\) matrix.
- Computes the matrix inverse (matInv) and derives the raw update step using matrix-vector multiplication (matVec). - Applies the exponential smoothing factor alpha to blend the old coefficients with the new ones. - Returns the new coefficient vector beta, the covariance matrix (inverse Hessian) cov, and total n.


