        var mu = Math.exp(eta);

        // Clamping per stabilità numerica
        if (mu &gt; 1e10 || mu &lt; 1e-10) continue;

        var w = mu;
        var z = eta + (y - mu) / mu;

        for (var i = 0; i &lt; p; i++) {
            XTWZ[i] += w * x[i] * z;
            for (var j = 0; j &lt; p; j++) {
                XTWX[i][j] += w * x[i] * x[j];
            }
        }
        nobs++;
    }

    return {
        xtwx: XTWX,
        xtwz: XTWZ,
        n: nobs
    };
}
